const raw = $input.first().json.output;

let parsed;

// ✅ STEP 1: Parse the full JSON string safely
try {
  parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error("Invalid JSON from AI agent");
}

// ✅ STEP 2: Validate structure
if (!Array.isArray(parsed)) {
  throw new Error("Expected an array of rows");
}

// ✅ STEP 3: Normalize & clean
const cleaned = parsed.map((item, index) => ({
  ...item,

  // enforce row_id sequence
  row_id: index + 1
}));

// ✅ STEP 5: Return as n8n items
return cleaned.map(item => ({
  json: item
}));

// Get estimate + rate data
const estimateData = $('Merge').first().json.data || [];
const rateData = $('Merge').last().json.rate_data || [];

if (!estimateData.length) {
  throw new Error("No estimate data found");
}

if (!rateData.length) {
  throw new Error("No rate data found");
}

// 🔴 SUPPLIER TASK TYPES (SOURCE OF TRUTH)

const supplierRaw =
  $('Aggregate1').first().json["Task Type"] || [];

const SUPPLIER_TASK_TYPES = new Set(
  supplierRaw.map(item => {
    const match = item.match(/^([A-Z0-9]+)/);
    return match ? match[1].trim() : null;
  }).filter(Boolean)
);

// Build rate lookup
const rateMap = {};
for (const r of rateData) {
  rateMap[r.task_types] = parseFloat(r.rate) || 0;
}

// Helper to format numbers → "0.00"
const format = (num) => Number(num || 0).toFixed(2);

let grandTotal = 0;

const results = estimateData.map((row, index) => {
  let units = parseFloat(row["Units"]);
  const taskType = row["Task Type Code"];

  if (!taskType) {
    throw new Error(`Missing Task Type Code at row ${index + 1}`);
  }

  // 🔴 DETERMINE TASK TYPE CATEGORY
  const isSupplierTask = SUPPLIER_TASK_TYPES.has(taskType);

  // 🔴 ENFORCE SYSTEM RULES (DO NOT TRUST INPUT)
  let chargeType;
  if (isSupplierTask) {
    chargeType = "Supplier";
    units = 1; // FORCE RULE
  } else {
    chargeType = "Time";

    // VALIDATE TIME UNITS
    if (!units || units <= 0) {
      throw new Error(`Invalid time units at row ${index + 1}`);
    }
  }

  const rate = rateMap[taskType] ?? 0;

  // 🔴 CALCULATIONS
  const base = units * rate;

  // ✅ MARKUP RULE (STRICT)
  const markup = chargeType === "Supplier" ? base * 0.20 : 0;

  const subTotal = base + markup;
  const tax = subTotal * 0.10;
  const total = subTotal + tax;

  grandTotal += total;

  return {
    json: {
      "Client": row["Client"] || "",
      "Product": row["Product"] || "",
      "Job No.": row["Job No."] || "",
      "Job Description": row["Job Description"] || "",
      "Version No.": row["Version No."] || "1.00",
      "Title": row["Title"] || "",
      "Superseded": "",
      "Date": "",
      "Currency Code": row["Currency Code"] || "A$",
      "Headings Description": row["Headings Description"] || "",

      // 🔴 SYSTEM-CONTROLLED FIELDS
      "Charge Type": chargeType,
      "Task Type Code": taskType,

      "Description": row["Description"] || "",
      "Units": format(units),
      "Rate": format(rate),
      "Mark Ups": format(markup),
      "Service Fee": "",
      "Tax": format(tax),
      "Estimate Total": format(total),
      "Estimate Notes": row["Estimate Notes"] || "",
      "Line Notes": ""
    }
  };
});

// OPTIONAL: attach grand total (if needed later)
return results;

const data = $input.first().json.data;

if (!Array.isArray(data)) {
  return [];
}

const clients = data.map(client => ({
  client_name: client.name || null,
  client_code: client.code || null
}));

return [{ json: { clients } }];

