// ======================================
// n8n CODE NODE
// Production Grade Brief JSON Parser
// ======================================

// ──────────────────────────────────────
// INPUT
// ──────────────────────────────────────

const raw = $input.first().json.content?.[0]?.text || '';

// ──────────────────────────────────────
// CLIENT MASTER LIST
// ──────────────────────────────────────

const clientMasterList =
  $('client_list')
    .first()
    .json
    .clients || [];

// Build:
// code -> name
const clientCodeToName = {};

for (const client of clientMasterList) {

  if (
    client?.client_code &&
    client?.client_name
  ) {

    clientCodeToName[
      String(client.client_code).trim()
    ] =
      String(client.client_name).trim();
  }
}

// Build:
// normalized name -> code
const clientNameToCode = {};

for (const client of clientMasterList) {

  if (
    client?.client_name &&
    client?.client_code
  ) {

    clientNameToCode[
      String(client.client_name)
        .toLowerCase()
        .trim()
    ] =
      String(client.client_code).trim();
  }
}

// ──────────────────────────────────────
// STEP 1: STRIP MARKDOWN
// ──────────────────────────────────────

let cleaned = String(raw || '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

// ──────────────────────────────────────
// STEP 2: FIND JSON START
// ──────────────────────────────────────

const start = cleaned.indexOf('{');

if (start === -1) {

  return [{
    json: {
      error: 'No JSON found',
      raw_preview: cleaned.substring(0, 500)
    }
  }];
}

cleaned = cleaned.substring(start);

// ──────────────────────────────────────
// STEP 3: CLEAN CHARACTERS
// ──────────────────────────────────────

cleaned = cleaned

  // control chars
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')

  // smart quotes
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')

  // dashes
  .replace(/–/g, '-')
  .replace(/—/g, '-')

  // tabs/newlines normalize
  .replace(/\t/g, ' ')
  .replace(/\r/g, ' ');

// ──────────────────────────────────────
// STEP 4: AUTO CLOSE TRUNCATED JSON
// ──────────────────────────────────────

const lastChar =
  cleaned.trim().slice(-1);

const isTruncated =
  lastChar !== '}';

if (isTruncated) {

  let braces = 0;
  let brackets = 0;
  let inString = false;
  let escape = false;

  for (let i = 0; i < cleaned.length; i++) {

    const c = cleaned[i];

    if (escape) {
      escape = false;
      continue;
    }

    if (c === '\\') {
      escape = true;
      continue;
    }

    if (c === '"') {
      inString = !inString;
      continue;
    }

    if (inString) continue;

    if (c === '{') braces++;
    if (c === '}') braces--;

    if (c === '[') brackets++;
    if (c === ']') brackets--;
  }

  // close string
  if (inString) {
    cleaned += '"';
  }

  // close arrays
  while (brackets > 0) {
    cleaned += ']';
    brackets--;
  }

  // close objects
  while (braces > 0) {
    cleaned += '}';
    braces--;
  }
}

// ──────────────────────────────────────
// STEP 5: REMOVE TRAILING COMMAS
// ──────────────────────────────────────

cleaned = cleaned
  .replace(/,\s*}/g, '}')
  .replace(/,\s*]/g, ']');

// ──────────────────────────────────────
// STEP 6: PARSE JSON
// ──────────────────────────────────────

let parsed;

try {

  parsed = JSON.parse(cleaned);

} catch (e) {

  const pos =
    parseInt(
      e.message.match(/position (\d+)/)?.[1]
    );

  return [{
    json: {

      error:
        `JSON parse failed: ${e.message}`,

      context:
        pos
          ? cleaned.substring(
              Math.max(0, pos - 150),
              pos + 150
            )
          : null,

      raw_output:
        cleaned.substring(0, 2000),

      fix_hint:
        'Increase max_tokens in Claude node'
    }
  }];
}

// ──────────────────────────────────────
// STEP 7: REQUIRED FIELDS
// ──────────────────────────────────────

const requiredFields = [

  'job_number',
  'client_name',
  'client_code',
  'project_description',
  'project_type',
  'proposition',
  'allocated_hours',
  'task',
  'deliverables',
  'deadline',
  'budget_range',
  'requirements',
  'team_preferences',
  'account_manager',
  'timeline_overview',
  'references'
];

const missingFields =
  requiredFields.filter(
    field => !(field in parsed)
  );

// ──────────────────────────────────────
// STEP 8: JOB NUMBER FALLBACK
// ──────────────────────────────────────

let jobNumberSource = 'claude';

if (!parsed.job_number) {

  const jobMatch =
    raw.match(/[A-Z]{4}[0-9]{4}/);

  if (jobMatch) {

    parsed.job_number =
      jobMatch[0];

    jobNumberSource =
      'regex_fallback';

  } else {

    jobNumberSource =
      'not_found';
  }
}

// ──────────────────────────────────────
// STEP 9: CLIENT VALIDATION
// ──────────────────────────────────────

const incompleteFlags = [];

let clientVerified = false;

let unmatched_client_raw = null;

// --------------------------------------
// 9A. VERIFY USING CLIENT CODE
// --------------------------------------

if (
  parsed.client_code &&
  clientCodeToName[parsed.client_code]
) {

  const expectedName =
    clientCodeToName[
      parsed.client_code
    ];

  clientVerified = true;

  if (
    parsed.client_name !== expectedName
  ) {

    parsed.client_name =
      expectedName;

    incompleteFlags.push(
      `client_name auto-corrected from client_code "${parsed.client_code}"`
    );
  }
}

// --------------------------------------
// 9B. INFER FROM JOB PREFIX
// --------------------------------------

else if (
  !parsed.client_code &&
  parsed.job_number
) {

  const prefix =
    String(parsed.job_number)
      .substring(0, 4);

  if (clientCodeToName[prefix]) {

    parsed.client_code = prefix;

    parsed.client_name =
      clientCodeToName[prefix];

    clientVerified = true;

    incompleteFlags.push(
      `client inferred from job prefix "${prefix}"`
    );
  }
}

// --------------------------------------
// 9C. REVERSE LOOKUP BY NAME
// --------------------------------------

if (
  !clientVerified &&
  parsed.client_name
) {

  const normalizedInput =
    String(parsed.client_name)
      .toLowerCase()
      .trim();

  const matchedCode =
    clientNameToCode[
      normalizedInput
    ];

  if (matchedCode) {

    parsed.client_code =
      matchedCode;

    parsed.client_name =
      clientCodeToName[
        matchedCode
      ];

    clientVerified = true;

    incompleteFlags.push(
      `client_code matched from client_name`
    );
  }
}

// --------------------------------------
// 9D. UNKNOWN CLIENT
// --------------------------------------

if (!clientVerified) {

  unmatched_client_raw =
    parsed.client_name || null;

  if (
    parsed.client_code &&
    !clientCodeToName[
      parsed.client_code
    ]
  ) {

    incompleteFlags.push(
      `UNKNOWN CLIENT CODE: "${parsed.client_code}"`
    );

  } else if (parsed.client_name) {

    incompleteFlags.push(
      `UNKNOWN CLIENT NAME: "${parsed.client_name}"`
    );

  } else {

    incompleteFlags.push(
      'client_name missing'
    );
  }
}

// ──────────────────────────────────────
// STEP 10: COMPLETENESS CHECKS
// ──────────────────────────────────────

if (!parsed.job_number) {
  incompleteFlags.push(
    'job_number missing'
  );
}

if (!parsed.project_type) {
  incompleteFlags.push(
    'project_type missing'
  );
}

if (!parsed.account_manager) {
  incompleteFlags.push(
    'account_manager missing'
  );
}

if (
  !parsed.deadline?.raw ||
  /\[|\]|TBD|TBC/i.test(
    parsed.deadline?.raw || ''
  )
) {

  incompleteFlags.push(
    'deadline missing or placeholder'
  );
}

if (
  !parsed.budget_range?.media?.min &&
  !parsed.budget_range?.production?.min
) {

  incompleteFlags.push(
    'budget figures missing'
  );
}

if (
  !parsed.timeline_overview ||
  parsed.timeline_overview.length === 0
) {

  incompleteFlags.push(
    'timeline missing'
  );
}

if (
  !parsed.requirements ||
  parsed.requirements.length === 0
) {

  incompleteFlags.push(
    'requirements missing'
  );
}

if (
  !parsed.deliverables ||
  parsed.deliverables.length === 0
) {

  incompleteFlags.push(
    'deliverables missing'
  );
}

// ──────────────────────────────────────
// STEP 11: OUTPUT
// ──────────────────────────────────────

return [{
  json: {

    ...parsed
  }
}];

// ============================================
// n8n CODE NODE
// Force Replace Job Number In Brief Text
// Production Grade
// ============================================

// ─────────────────────────────────────────────
// INPUTS
// ─────────────────────────────────────────────

const rawBrief =
$input.first().json.brief_data  || '';

const providedJobNumber =
  String(
    $input.first()?.json?.job_Number || ''
  ).trim();

// ─────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────

function normalizeText(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value)
    .replace(/\r/g, '\n')
    .replace(/\t/g, ' ')
    .trim();
}

function extractJobNumbers(text) {

  if (!text) {
    return [];
  }

  // EXACT RULE:
  // 4 uppercase letters + 4 digits

  const regex =
    /\b[A-Z]{4}[0-9]{4}\b/g;

  const matches =
    text.match(regex) || [];

  return [...new Set(matches)];
}

// ─────────────────────────────────────────────
// NORMALIZE
// ─────────────────────────────────────────────

let briefText =
  normalizeText(rawBrief);

// ─────────────────────────────────────────────
// VALIDATION
// ─────────────────────────────────────────────

if (!briefText) {

  return [{
    json: {
      success: false,
      error: 'Brief text is empty'
    }
  }];
}

if (!providedJobNumber) {

  return [{
    json: {
      success: false,
      error: 'Provided job number is missing'
    }
  }];
}

// ─────────────────────────────────────────────
// FIND EXISTING JOB NUMBERS
// ─────────────────────────────────────────────

const existingJobNumbers =
  extractJobNumbers(briefText);

// ─────────────────────────────────────────────
// REMOVE EXISTING JOB NUMBERS
// ─────────────────────────────────────────────

let cleanedBriefText =
  briefText.replace(
    /\b[A-Z]{4}[0-9]{4}\b/g,
    ''
  );

// Remove empty spaces caused by replacement
cleanedBriefText =
  cleanedBriefText
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

// ─────────────────────────────────────────────
// INSERT PROVIDED JOB NUMBER
// ─────────────────────────────────────────────

const updatedBriefText =
`Job Number: ${providedJobNumber}

${cleanedBriefText}`;

// ─────────────────────────────────────────────
// OUTPUT
// ─────────────────────────────────────────────

return [{
  json: {

    success: true,

    action:
      existingJobNumbers.length > 0
        ? 'job_number_replaced'
        : 'job_number_inserted',

    provided_job_number:
      providedJobNumber,

    removed_job_numbers:
      existingJobNumbers,

    output: {
      brief_text:
        updatedBriefText
    }
  }
}];

// ============================================
// INPUT
// ============================================

const allInputs = $input.all();

const outputs = [];

// ============================================
// PROCESS EACH INPUT ITEM SEPARATELY
// ============================================

for (const inputItem of allInputs) {

  const estimateData =
    inputItem.json.estimate_data || [];

  if (!estimateData.length) {
    continue;
  }

  const source = estimateData[0];

  const raw =
    source.pageContent || '';

  const rows = [];

  const seen = new Set();

  // ============================================
  // SPLIT TASKS
  // ============================================

  const chunks =
    raw.split(/Task Type:\s*/)
       .slice(1);

  // ============================================
  // PROCESS TASKS
  // ============================================

  for (const chunk of chunks) {

    // TASK TYPE

    const taskTypeMatch =
      chunk.match(/^([A-Z]{4,5})\b/);

    const task_type_code =
      taskTypeMatch
        ? taskTypeMatch[1].trim()
        : '';

    if (!task_type_code) {
      continue;
    }

    // DESCRIPTION

    const descriptionMatch =
      chunk.match(
        /Description:\s*(.*?)\s*Units:/s
      );

    const description =
      descriptionMatch
        ? descriptionMatch[1].trim()
        : '';

    // UNITS

    const unitsMatch =
      chunk.match(
        /Units:\s*([\d.]+)/
      );

    const units =
      unitsMatch
        ? parseFloat(unitsMatch[1])
        : 0;

    // RATE

    const rateMatch =
      chunk.match(
        /Rate:\s*([\d.]+)/
      );

    const rate =
      rateMatch
        ? parseFloat(rateMatch[1])
        : 0;

    // CHARGE TYPE

    const chargeTypeMatch =
      chunk.match(
        /Charge Type:\s*(.*?)\s*Description:/s
      );

    const charge_type =
      chargeTypeMatch
        ? chargeTypeMatch[1].trim()
        : '';

    // HEADING

    let heading = '';

    const headingMatch =
      chunk.match(
        /(.*?)Charge Type:/s
      );

    const headingSearch =
      headingMatch?.[1]?.match(
        /Heading:\s*(.*?)\s*$/
      );

    if (headingSearch) {
      heading =
        headingSearch[1].trim();
    }

    // ============================================
    // REMOVE DUPLICATE ROWS INSIDE SAME ESTIMATE
    // ============================================

    const uniqueKey =
      `${task_type_code}_${description}_${rate}_${units}`;

    if (seen.has(uniqueKey)) {
      continue;
    }

    seen.add(uniqueKey);

    rows.push({

      row_id:
        rows.length + 1,

      job_type:
        source.job_type || '',

      job_number:
        source.job_number || '',

      client_name:
        source.client_name || '',

      heading,

      task_type_code,

      description,

      units,

      rate,

      charge_type

    });
  }

  // ============================================
  // ONE OUTPUT ITEM PER INPUT ITEM
  // ============================================

  outputs.push({

    json: {

      job_number:
        source.job_number || '',

      client_name:
        source.client_name || '',

      job_type:
        source.job_type || '',

      row_count:
        rows.length,

      estimate_data:
        rows

    }

  });

}

// ============================================
// OUTPUT
// ============================================
return [
  {
    json: {
      similar_estimates: outputs.map(item => item.json)
    }
  }
];

// ============================================
// FILTER ALLOWED ATTENDEE EMAILS
// ============================================

const attendees =
  $('Fireflies Transcript Data')
    .first()
    .json
    .host_email || [];

// ============================================
// ALLOWED EMAILS
// ============================================

const allowedEmails = [
  'joseph@thecoreagency.com.au',
  'milton@thecoreagency.com.au',
  'rebecca@thecoreagency.com.au',
  'chris@automateshub.ai'
];

// ============================================
// FILTER
// ============================================

const filteredEmails =
  attendees
    .map(item => item.email)
    .filter(email =>
      allowedEmails.includes(
        String(email).toLowerCase()
      )
    );

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {
      filtered_email: filteredEmails
    }
  }
];

// ============================================
// n8n CODE NODE
// Extract Sender Emails
// One Item Per Email
// ============================================

function normalizeEmail(email) {

  if (
    email === null ||
    email === undefined
  ) {
    return null;
  }

  return String(email)
    .trim()
    .toLowerCase();
}

function isValidEmail(email) {

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(email);
}

const results = [];

for (const item of $input.all()) {

  const fromValues =
    Array.isArray(item?.json?.from?.value)
      ? item.json.from.value
      : [];

  for (const sender of fromValues) {

    const email =
      normalizeEmail(
        sender?.address
      );

    if (
      email &&
      isValidEmail(email)
    ) {

      results.push({
        json: {
          success: true,
          email: email
        }
      });
    }
  }
}

return results;

