// ============================================
// CHECK IF ANY ESTIMATE LINE HAS RATE = 0
// ============================================

const items = $input.all();

let foundZeroRate = false;
const zeroRateItems = [];

for (const item of items) {

  const data = item.json.data || [];

  for (const line of data) {

    const rate =
      parseFloat(line?.Rate || 0);

    if (rate === 0) {

      foundZeroRate = true;

      zeroRateItems.push({
        description: line.Description || "",
        task_type: line["Task Type Code"] || "",
        rate: line.Rate || "0.00"
      });
    }
  }
}

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {

      status: foundZeroRate
        ? "found: estimate has rate 0"
        : "not found",

      found_zero_rate: foundZeroRate,

      total_zero_rate_lines:
        zeroRateItems.length,

      zero_rate_items:
        zeroRateItems

    }
  }
];

