// ============================================
// INPUT
// ============================================

const allInputs = $input.all();

const results = [];

const seen = new Set();

// ============================================
// PROCESS ALL INPUTS
// ============================================

for (const inputItem of allInputs) {

  const estimateData =
    inputItem.json.estimate_data || [];

  if (!estimateData.length) {
    continue;
  }

  const source =
    estimateData[0];

  const raw =
    source.pageContent || '';

  // ============================================
  // SPLIT BY TASK TYPE
  // ============================================

  const chunks =
    raw.split(/Task Type:\s*/)
       .slice(1);

  // ============================================
  // PROCESS EACH CHUNK
  // ============================================

  for (const chunk of chunks) {

    // ----------------------------------------
    // TASK TYPE
    // ----------------------------------------

    const taskTypeMatch =
      chunk.match(/^([A-Z]{4,5})\b/);

    const task_type_code =
      taskTypeMatch
        ? taskTypeMatch[1].trim()
        : '';

    if (!task_type_code) {
      continue;
    }

    // ----------------------------------------
    // DESCRIPTION
    // ----------------------------------------

    const descriptionMatch =
      chunk.match(
        /Description:\s*(.*?)\s*Units:/s
      );

    const description =
      descriptionMatch
        ? descriptionMatch[1].trim()
        : '';

    // ----------------------------------------
    // UNITS
    // ----------------------------------------

    const unitsMatch =
      chunk.match(
        /Units:\s*([\d.]+)/
      );

    const units =
      unitsMatch
        ? parseFloat(unitsMatch[1])
        : 0;

    // ----------------------------------------
    // RATE
    // ----------------------------------------

    const rateMatch =
      chunk.match(
        /Rate:\s*([\d.]+)/
      );

    const rate =
      rateMatch
        ? parseFloat(rateMatch[1])
        : 0;

    // ----------------------------------------
    // CHARGE TYPE
    // ----------------------------------------

    const chargeTypeMatch =
      chunk.match(
        /Charge Type:\s*(.*?)\s*Description:/s
      );

    const charge_type =
      chargeTypeMatch
        ? chargeTypeMatch[1].trim()
        : '';

    // ----------------------------------------
    // HEADING
    // ----------------------------------------

    const headingMatch =
      chunk.match(
        /(.*?)Charge Type:/s
      );

    let heading = '';

    const headingSearch =
      headingMatch?.[1]
        ?.match(
          /Heading:\s*(.*?)\s*$/
        );

    if (headingSearch) {

      heading =
        headingSearch[1].trim();
    }

    // ========================================
    // REMOVE DUPLICATES
    // ========================================

    const uniqueKey =
      `${source.job_number}_${task_type_code}_${description}_${rate}`;

    if (seen.has(uniqueKey)) {
      continue;
    }

    seen.add(uniqueKey);

    // ========================================
    // PUSH RESULT
    // ========================================

    results.push({

      row_id:
        results.length + 1,

      job_type:
        source.job_type || '',

      job_number:
        source.job_number || '',

      client_name:
        source.client_name || '',

      heading,

      task_type_code,

      description,

      units,

      rate,

      charge_type

    });
  }
}

// ============================================
// GROUP BY JOB NUMBER
// ============================================

const grouped = {};

results.forEach((row) => {

  const job =
    row.job_number || 'UNKNOWN';

  if (!grouped[job]) {

    grouped[job] = {

      job_number: job,

      client_name:
        row.client_name,

      job_type:
        row.job_type,

      row_count: 0,

      estimate_data: []

    };
  }

  grouped[job]
    .estimate_data
    .push(row);

  grouped[job]
    .row_count++;
});

// ============================================
// CREATE FINAL OUTPUT
// ============================================

const finalOutput = {};

Object.values(grouped)
  .forEach((item, index) => {

    finalOutput[`estimate_${index}`] =
      item;

  });

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: finalOutput
  }
];

const items = $input.all();

// Get estimate + rate data
const estimateData = items[0]?.json?.data || [];
const rateData = items[1]?.json?.rate_data || [];

if (!estimateData.length) {
  throw new Error("No estimate data found");
}

if (!rateData.length) {
  throw new Error("No rate data found");
}

// 🔴 SUPPLIER TASK TYPES (SOURCE OF TRUTH)
const SUPPLIER_TASK_TYPES = new Set([
  "EXDE",
  "EXMO",
  "EXSD",
  "FRED",
  "TALT",
  "MUSI",
  "STEX",
  "MISC"
]);

// Build rate lookup
const rateMap = {};
for (const r of rateData) {
  rateMap[r.task_types] = parseFloat(r.rate) || 0;
}

// Helper to format numbers → "0.00"
const format = (num) => Number(num || 0).toFixed(2);

let grandTotal = 0;

const results = estimateData.map((row, index) => {
  let units = parseFloat(row["Units"]);
  const taskType = row["Task Type Code"];

  if (!taskType) {
    throw new Error(`Missing Task Type Code at row ${index + 1}`);
  }

  // 🔴 DETERMINE TASK TYPE CATEGORY
  const isSupplierTask = SUPPLIER_TASK_TYPES.has(taskType);

  // 🔴 ENFORCE SYSTEM RULES (DO NOT TRUST INPUT)
  let chargeType;
  if (isSupplierTask) {
    chargeType = "Supplier";
    units = 1; // FORCE RULE
  } else {
    chargeType = "Time";

    // VALIDATE TIME UNITS
    if (!units || units <= 0) {
      throw new Error(`Invalid time units at row ${index + 1}`);
    }
  }

  const rate = rateMap[taskType] ?? 0;

  // 🔴 CALCULATIONS
  const base = units * rate;

  // ✅ MARKUP RULE (STRICT)
  const markup = chargeType === "Supplier" ? base * 0.20 : 0;

  const subTotal = base + markup;
  const tax = subTotal * 0.10;
  const total = subTotal + tax;

  grandTotal += total;

  return {
    json: {
      "Client": row["Client"] || "",
      "Product": row["Product"] || "",
      "Job No.": row["Job No."] || "",
      "Job Description": row["Job Description"] || "",
      "Version No.": row["Version No."] || "1.00",
      "Title": row["Title"] || "",
      "Superseded": "",
      "Date": "",
      "Currency Code": row["Currency Code"] || "A$",
      "Headings Description": row["Headings Description"] || "",

      // 🔴 SYSTEM-CONTROLLED FIELDS
      "Charge Type": chargeType,
      "Task Type Code": taskType,

      "Description": row["Description"] || "",
      "Units": format(units),
      "Rate": format(rate),
      "Mark Ups": format(markup),
      "Service Fee": "",
      "Tax": format(tax),
      "Estimate Total": format(total),
      "Estimate Notes": row["Estimate Notes"] || "",
      "Line Notes": ""
    }
  };
});

// OPTIONAL: attach grand total (if needed later)
return results;

// ============================================
// FILTER ALLOWED ATTENDEE EMAILS
// ============================================

const attendees =
  $('Fireflies Transcript Data')
    .first()
    .json
    .attendees_email || [];

// ============================================
// ALLOWED EMAILS
// ============================================

const allowedEmails = [
  'joseph@thecoreagency.com.au',
  'milton@thecoreagency.com.au',
  'rebecca@thecoreagency.com.au',
  'chris@automateshub.ai'
];

// ============================================
// FILTER
// ============================================

const filteredEmails =
  attendees
    .map(item => item.email)
    .filter(email =>
      allowedEmails.includes(
        String(email).toLowerCase()
      )
    );

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {
      filtered_emails: filteredEmails
    }
  }
];

const hostEmail = String(
  $('Fireflies Transcript Data')
    .first()
    .json
    .host_email || ''
).toLowerCase();

const allowedEmails = [
  'joseph@thecoreagency.com.au',
  'milton@thecoreagency.com.au',
  'jen@thecoreagency.com.au'
];

return [{
  json: {
    filtered_email: allowedEmails.includes(hostEmail)
      ? hostEmail
      : null
  }
}];

// ============================================
// n8n CODE NODE
// Extract Sender Emails
// One Item Per Email
// ============================================

function normalizeEmail(email) {

  if (
    email === null ||
    email === undefined
  ) {
    return null;
  }

  return String(email)
    .trim()
    .toLowerCase();
}

function isValidEmail(email) {

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(email);
}

const results = [];

for (const item of $input.all()) {

  const fromValues =
    Array.isArray(item?.json?.from?.value)
      ? item.json.from.value
      : [];

  for (const sender of fromValues) {

    const email =
      normalizeEmail(
        sender?.address
      );

    if (
      email &&
      isValidEmail(email)
    ) {

      results.push({
        json: {
          success: true,
          emails: [email]
        }
      });
    }
  }
}

return results;

const ALLOWED_EXTENSIONS = new Set([
  'pdf',
  'doc',

  'ppt',
  'pptx'
]);

const output = [];

for (const [binaryKey, binaryFile] of Object.entries($binary ?? {})) {

  const extension = String(binaryFile.fileExtension || '')
    .trim()
    .toLowerCase();

  if (!ALLOWED_EXTENSIONS.has(extension)) {
    continue;
  }

  output.push({
    json: {
      ...$json,
      hasSupportedAttachment: true,
      fileExtension: extension,
    },
    binary: {
      brief_0: binaryFile,
    },
  });
}

if (output.length === 0) {
  return [{
    json: {
      ...$json,
      hasSupportedAttachment: false,
      message: 'No supported attachment found.'
    }
  }];
}

return output;

const hostEmail = String(
  $('Fireflies Transcript Data')
    .first()
    .json
    .host_email || ''
).toLowerCase();

const allowedEmails = [
  'joseph@thecoreagency.com.au',
  'milton@thecoreagency.com.au',
  'rebecca@thecoreagency.com.au'
];

return [{
  json: {
    filtered_email: allowedEmails.includes(hostEmail)
      ? hostEmail
      : null
  }
}];
